(async()=>{if(new URLSearchParams(location.search).get('profile')!=='lighting-check')return;const wait=ms=>new Promise(r=>setTimeout(r,ms));while(!window.EmberQA)await wait(100);const q=EmberQA,D=SurvivalData,W=EmberTerrain;document.getElementById('welcome').hidden=true;q.close(false);q.setPlaying(false);const out=document.createElement('section');out.style='position:fixed;inset:0;overflow:auto;z-index:10000;background:white;color:#234;padding:20px';document.body.append(out);const report=document.createElement('pre');report.id='report';out.append(report);const rows=[];for(const weather of ['clear','rain'])for(const hour of [12,16,17,18,18.5,19.2,23]){q.apply({...D.fresh(),worldTime:hour/24*720,automaticTime:false,weatherMode:weather,x:-17,z:30,y:W.ground(-17,30),yaw:0,pitch:0});q.sky.update(q.state,0,true);await wait(250);const sky=q.sky;rows.push({weather,hour,sun:sky.sun.intensity,ambient:sky.ambient.intensity,skyLight:sky.atmosphere.update(q.camera,sky.cycle.day,sky.cycle.worldTime,sky.cycle.sample().cloudCover,0,0,sky.cycle.worldDays).skyLight});if(weather==='clear'&&[12,17,18,18.5,23].includes(hour)){await wait(700);q.renderer.render(q.scene,q.camera);const im=document.createElement('img');im.id='hour-'+hour;im.alt=hour+':00';im.src=q.renderer.domElement.toDataURL();im.style='width:49%';out.append(im);}}const cave=W.caves[0],pt=cave.spawnPoints[1],floor=pt.y;q.apply({...D.fresh(),x:pt.x,z:pt.z,y:floor,worldTime:360});const env=q.sky.update(q.state,0,true);if(env.caveDepth<.99)throw Error('Cave sample must be underground');if(rows.find(r=>r.weather==='clear'&&r.hour===18).ambient<.4)throw Error('Sunset too dark');if(rows.find(r=>r.weather==='rain'&&r.hour===17).ambient<.6)throw Error('Overcast afternoon too dark');report.textContent=JSON.stringify({rows,cave:{depth:env.caveDepth,ambient:q.sky.ambient.intensity}},null,2);document.title='時刻と明るさ確認完了';})().catch(e=>{const p=document.createElement('pre');p.id='report';p.textContent=e.stack;document.body.append(p);});
